<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Когда аванс попадает под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Когда контракт по источнику и сумме входит в перечень статьи 5 Закона № 426-ФЗ: авансы по госконтрактам от 100 млн ₽, авансы соисполнителей свыше 3 млн ₽, авансы по контрактам за счёт субсидий, авансы по ГОЗ свыше 3 млн ₽."}}, {"@type": "Question", "name": "Какой размер аванса можно получить при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Размер устанавливает заказчик в пределах, заданных Правительством. По общему правилу для федеральных нужд — до 30% цены контракта, при казначейском сопровождении нередко выше (до 50%), а в отдельных случаях — повышенное авансирование. Конкретный размер смотрите в документации закупки."}}, {"@type": "Question", "name": "Куда перечисляется аванс под сопровождением?", "acceptedAnswer": {"@type": "Answer", "text": "На лицевой счёт исполнителя в территориальном органе казначейства (счёт 71), а не на банковский расчётный счёт. Расходование идёт под санкционирование каждого платежа."}}, {"@type": "Question", "name": "Нужно ли обеспечение при авансе?", "acceptedAnswer": {"@type": "Answer", "text": "Да. По 44-ФЗ, если аванс превышает 30% цены контракта, обеспечение исполнения устанавливается не меньше суммы аванса. Дополнительно действует антидемпинговый механизм при сильном снижении цены на торгах."}}, {"@type": "Question", "name": "Можно ли потратить аванс на любые расходы?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Только на цели, связанные с исполнением контракта и заранее отражённые в сведениях об операциях с целевыми средствами. Нецелевые платежи казначейство возвращает."}}, {"@type": "Question", "name": "Что такое казначейское обеспечение обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Альтернатива «живому» авансу: вместо денег на счёт исполнитель получает казначейское обеспечение, а оплата соисполнителям проходит через казначейство под фактическую поставку. Регулируется статьёй 242.22 БК и статьёй 5 Закона № 426-ФЗ."}}, {"@type": "Question", "name": "Почему казначейство вернуло платёж с аванса?", "acceptedAnswer": {"@type": "Answer", "text": "Чаще всего — расход не отражён в сведениях об операциях, неверное назначение платежа или код, отсутствует документ-основание либо расход не связан с контрактом."}}, {"@type": "Question", "name": "Когда открывать лицевой счёт под аванс?", "acceptedAnswer": {"@type": "Answer", "text": "До подписания контракта или до даты перечисления аванса. Без открытого счёта 71 заказчик не сможет перечислить предоплату под сопровождением."}}, {"@type": "Question", "name": "Чем аванс под казначейское сопровождение отличается от обычной предоплаты?", "acceptedAnswer": {"@type": "Answer", "text": "Обычный аванс идёт на банковский счёт и расходуется свободно. Аванс под казначейским сопровождением зачисляется на лицевой счёт в ТОФК и тратится только под санкционирование, по целевому назначению, отражённому в сведениях об операциях."}}, {"@type": "Question", "name": "Можно ли вывести аванс как прибыль до выполнения работ?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Средства аванса на лицевом счёте целевые: ими нельзя закрыть кассовый разрыв по другому контракту или вывести как прибыль до отработки. Допустимы только расходы по исполнению этого контракта."}}]}
